#include "tigersheets/main_window.hpp"
#include "tigersheets/grid.hpp"
#include <QApplication>
#include <QClipboard>
#include <QKeyEvent>
#include <QTableView>
#include <QTemporaryDir>
#include <QVariantAnimation>
#include <QTabBar>
#include <QScrollBar>
#include <QtTest/QTest>
#include <iostream>
#include <stdexcept>
using namespace tigersheets;
void require(bool okay,const char* message){if(!okay)throw std::runtime_error(message);}
void copySourceAnimates(){
 MainWindow window;window.show();QApplication::processEvents();auto* grid=window.findChild<QTableView*>("worksheet.grid");auto* model=dynamic_cast<WorksheetModel*>(grid->model());require(model->setData(model->index(1,1),"12",Qt::EditRole),"seed copy source");const auto first=model->index(1,1),last=model->index(2,2);grid->setCurrentIndex(first);grid->selectionModel()->select(QItemSelection(first,last),QItemSelectionModel::ClearAndSelect);const auto before=window.currentSession().snapshot();
 require(window.executeCommand("copy"),"copy a rectangular selection");QApplication::processEvents();auto* border=grid->viewport()->findChild<QWidget*>("worksheet.copyBorder");require(border&&border->isVisible(),"Copy must display a source-range border");require(border->property("sourceRect").toRect()==grid->visualRect(first).united(grid->visualRect(last)).adjusted(1,1,-1,-1),"copy border surrounds the complete source rectangle");auto* animation=border->findChild<QVariantAnimation*>("worksheet.copyAnimation");require(animation&&animation->state()==QAbstractAnimation::Running,"copy border must animate automatically");const auto phase=border->property("dashOffset").toReal();animation->setCurrentTime(150);require(border->property("dashOffset").toReal()!=phase,"advancing the animation moves the painted dash offset");grid->setCurrentIndex(model->index(5,4));require(border->property("sourceRect").toRect()==grid->visualRect(first).united(grid->visualRect(last)).adjusted(1,1,-1,-1),"navigation leaves marching dashes on the copied cells");require(window.currentSession().snapshot()==before,"copy animation and navigation never mutate the workbook or history");
}
void copyCancellation(bool replacement){
 MainWindow window;window.show();QApplication::processEvents();auto* grid=window.findChild<QTableView*>("worksheet.grid");auto* model=dynamic_cast<WorksheetModel*>(grid->model());require(model->setData(model->index(0,0),"23",Qt::EditRole)&&window.executeCommand("copy"),"copy before cancellation");auto* border=grid->viewport()->findChild<QWidget*>("worksheet.copyBorder");auto* animation=border->findChild<QVariantAnimation*>("worksheet.copyAnimation");const auto before=window.currentSession().snapshot();if(replacement)QApplication::clipboard()->setText("copied from another application");else{grid->setFocus();QKeyEvent escape(QEvent::KeyPress,Qt::Key_Escape,Qt::NoModifier);QApplication::sendEvent(grid,&escape);}require(!border->isVisible()&&animation->state()==QAbstractAnimation::Stopped,replacement?"replacing the clipboard cancels the old copy animation":"Escape cancels the copy animation");require(window.currentSession().snapshot()==before,"copy cancellation leaves values and history untouched");
}
void repeatedPasteAndSheetSwitch(){
 MainWindow window;window.show();QApplication::processEvents();auto* grid=window.findChild<QTableView*>("worksheet.grid");auto* model=dynamic_cast<WorksheetModel*>(grid->model());auto* tabs=window.findChild<QTabBar*>("workspace.sheets");require(window.executeCommand("sheet.add"),"create another worksheet before copying");tabs->setCurrentIndex(0);grid->setCurrentIndex(model->index(0,0));require(model->setData(model->index(0,0),"23",Qt::EditRole)&&window.executeCommand("copy"),"copy before repeated pastes");auto* border=grid->viewport()->findChild<QWidget*>("worksheet.copyBorder");auto* animation=border->findChild<QVariantAnimation*>("worksheet.copyAnimation");const auto source=border->property("sourceRect").toRect();
 for(const int row:{2,4}){grid->setCurrentIndex(model->index(row,0));require(window.executeCommand("paste")&&model->raw(row,0)=="23","copy supports repeated paste");require(border->isVisible()&&border->property("sourceRect").toRect()==source&&animation->state()==QAbstractAnimation::Running,"repeated paste retains the animated source border");}const auto before=window.currentSession().snapshot();window.recalculateNow();require(border->isVisible()&&window.currentSession().snapshot()==before,"calculation refresh preserves copy mode and history");tabs->setCurrentIndex(1);require(!border->isVisible()&&animation->state()!=QAbstractAnimation::Running,"copy animation hides and pauses on other worksheets");tabs->setCurrentIndex(0);require(border->isVisible()&&animation->state()==QAbstractAnimation::Running&&border->property("sourceRect").toRect()==source,"returning to the source sheet restores its animated border");
}
void workbookAndEditCancellation(bool reopen){
 MainWindow window;window.show();QApplication::processEvents();auto* grid=window.findChild<QTableView*>("worksheet.grid");auto* model=dynamic_cast<WorksheetModel*>(grid->model());require(model->setData(model->index(0,0),"23",Qt::EditRole),"seed copy before workbook change");QTemporaryDir files;const auto path=files.filePath("copied.xlsx");if(reopen)require(window.saveWorkbook(path),"save source workbook before copying");require(window.executeCommand("copy"),"copy before workbook or editing action");auto* border=grid->viewport()->findChild<QWidget*>("worksheet.copyBorder");auto* animation=border->findChild<QVariantAnimation*>("worksheet.copyAnimation");if(reopen)require(window.openWorkbook(path),"reopen a workbook with the same sheet identifiers");else require(window.executeCommand("cells.format",{{"style",{{"bold",true}}}}),"formatting makes a real revision change");require(!border->isVisible()&&animation->state()==QAbstractAnimation::Stopped,reopen?"opening a workbook cancels the previous copy mode":"a workbook editing action cancels the source animation");
}
void frozenCopyOutline(){
 MainWindow window;window.show();QApplication::processEvents();auto* grid=window.findChild<QTableView*>("worksheet.grid");auto* model=dynamic_cast<WorksheetModel*>(grid->model());const auto first=model->index(0,0),last=model->index(2,1);grid->setCurrentIndex(first);grid->selectionModel()->select(QItemSelection(first,last),QItemSelectionModel::ClearAndSelect);require(window.executeCommand("copy")&&window.executeCommand("view.freeze"),"copy a range crossing the frozen top row");QApplication::processEvents();auto* frozen=window.findChild<QTableView*>("worksheet.frozen");require(frozen,"frozen worksheet exists");auto* frozenBorder=frozen->viewport()->findChild<QWidget*>("worksheet.copyBorder");require(frozenBorder&&frozenBorder->isVisible(),"frozen top row shows the copied range's animated border");auto* bodyBorder=grid->viewport()->findChild<QWidget*>("worksheet.copyBorder");require(bodyBorder->property("sourceRect").toRect().top()<0,"the scrolling body must not invent a top border below the frozen row");frozen->setFocus();QKeyEvent escape(QEvent::KeyPress,Qt::Key_Escape,Qt::NoModifier);QApplication::sendEvent(frozen,&escape);require(!frozenBorder->isVisible()&&!bodyBorder->isVisible(),"Escape in the frozen worksheet cancels both copy outlines");require(window.executeCommand("copy"),"copy again before editing a frozen-row cell");const auto before=window.currentSession().snapshot();frozen->setCurrentIndex(model->index(0,0));QTest::keyClick(frozen,Qt::Key_F2);require(!frozenBorder->isVisible()&&!bodyBorder->isVisible()&&window.currentSession().snapshot()==before,"starting a frozen-row edit cancels both outlines without a workbook mutation");
}
void scrollingCopyOutline(){
 MainWindow window;window.show();QApplication::processEvents();auto* grid=window.findChild<QTableView*>("worksheet.grid");auto* model=dynamic_cast<WorksheetModel*>(grid->model());const auto first=model->index(1,1),last=model->index(2,2);grid->setCurrentIndex(first);grid->selectionModel()->select(QItemSelection(first,last),QItemSelectionModel::ClearAndSelect);require(window.executeCommand("copy"),"copy before scrolling");auto* border=grid->viewport()->findChild<QWidget*>("worksheet.copyBorder");auto* animation=border->findChild<QVariantAnimation*>("worksheet.copyAnimation");grid->horizontalScrollBar()->setValue(170);grid->verticalScrollBar()->setValue(40);const auto source=border->property("sourceRect").toRect();require(source.left()<0&&source.top()<0&&source==grid->visualRect(first).united(grid->visualRect(last)).adjusted(1,1,-1,-1),"partially scrolled copy retains true offscreen edges instead of fabricating viewport edges");require(border->geometry()==grid->viewport()->rect(),"copy overlay stays attached to the viewport while scrolling");grid->verticalScrollBar()->setValue(200);require(!border->isVisible()&&animation->state()==QAbstractAnimation::Paused,"fully offscreen copy pauses its animation");grid->horizontalScrollBar()->setValue(0);grid->verticalScrollBar()->setValue(0);window.resize(window.width()+120,window.height()+40);QApplication::processEvents();require(border->isVisible()&&animation->state()==QAbstractAnimation::Running&&border->geometry()==grid->viewport()->rect(),"scrolling back and resizing restore the correctly sized copy overlay");const auto before=window.currentSession().snapshot();grid->setFocus();QTest::keyClick(grid,Qt::Key_F2);require(!border->isVisible()&&animation->state()==QAbstractAnimation::Stopped&&window.currentSession().snapshot()==before,"starting a cell edit cancels copy animation without committing a change");
}
void cutLifecycle(){
 MainWindow window;window.show();QApplication::processEvents();auto* grid=window.findChild<QTableView*>("worksheet.grid");auto* model=dynamic_cast<WorksheetModel*>(grid->model());
 require(model->setData(model->index(0,0),"10",Qt::EditRole)&&model->setData(model->index(0,1),"=A1*2",Qt::EditRole),"clipboard UI setup");grid->setCurrentIndex(model->index(0,1));const auto before=window.currentSession().snapshot();
 require(window.executeCommand("cut")&&window.currentSession().snapshot()==before,"native Cut command defers mutation");auto* border=grid->viewport()->findChild<QWidget*>("worksheet.copyBorder");require(border&&border->isVisible(),"Cut displays the animated source border too");grid->setFocus();QKeyEvent escape(QEvent::KeyPress,Qt::Key_Escape,Qt::NoModifier);QApplication::sendEvent(grid,&escape);
 require(QApplication::clipboard()->text().isEmpty(),"Escape on the worksheet cancels and clears the pending cut clipboard");require(window.currentSession().snapshot()==before,"cancelling Cut leaves source and undo history untouched");
 require(!border->isVisible(),"Escape clears the cut outline");require(window.executeCommand("cut"),"cut again after cancel");grid->setCurrentIndex(model->index(1,1));require(!window.executeCommand("paste.special",{{"mode","values"}})&&border->isVisible()&&window.currentSession().snapshot()==before,"failed cut Paste Special retains the source animation and data");require(window.executeCommand("paste"),"native Paste moves cut source");require(model->raw(0,1).isEmpty()&&model->raw(1,1)=="=A1*2","native Cut/Paste uses move reference semantics");require(QApplication::clipboard()->text().isEmpty()&&!border->isVisible(),"successful move consumes the cut clipboard and animation");require(window.executeCommand("undo")&&window.currentSession().snapshot().at("sheets")==before.at("sheets"),"native move undo restores the whole source/destination change");
}
int main(int argc,char**argv){QApplication app(argc,argv);QTemporaryDir state;qputenv("TIGERSHEETS_STATE_DIR",state.path().toUtf8());try{const auto selected=argc>1?std::string(argv[1]):std::string();if(selected.empty()||selected=="copy_animation")copySourceAnimates();if(selected.empty()||selected=="copy_escape")copyCancellation(false);if(selected.empty()||selected=="clipboard_replace")copyCancellation(true);if(selected.empty()||selected=="repeat_paste")repeatedPasteAndSheetSwitch();if(selected.empty()||selected=="copy_edit")workbookAndEditCancellation(false);if(selected.empty()||selected=="copy_reopen")workbookAndEditCancellation(true);if(selected.empty()||selected=="frozen_copy")frozenCopyOutline();if(selected.empty()||selected=="copy_scroll")scrollingCopyOutline();if(selected.empty()||selected=="cut")cutLifecycle();std::cout<<"worksheet clipboard UI passed\n";
 }catch(const std::exception& error){std::cerr<<"FAILED: "<<error.what()<<'\n';return 1;}}
